rm -f hn-top.txt
python3 - <<'PY' || echo 'FETCH_FAIL hn-top.txt'
import concurrent.futures as cf, json, sys, time, urllib.request
UA = {"User-Agent": "Mozilla/5.0 (compatible; pervio-github-daily/2.0)"}
DEADLINE = time.time() + 55
def get(u, t):
    return json.load(urllib.request.urlopen(urllib.request.Request(u, headers=UA), timeout=t))
ids = get("https://hacker-news.firebaseio.com/v0/topstories.json", 20)[:30]
def item(i):
    t = DEADLINE - time.time()
    if t <= 1:
        return None
    try:
        it = get("https://hacker-news.firebaseio.com/v0/item/%d.json" % i, min(t, 15))
    except Exception:
        return None
    if not isinstance(it, dict) or it.get("type") != "story" or it.get("dead") or it.get("deleted"):
        return None
    title = " ".join(str(it.get("title") or "").split())
    url = " ".join(str(it.get("url") or "https://news.ycombinator.com/item?id=%d" % i).split())
    score = int(it.get("score") or 0)
    comments = int(it.get("descendants") or 0)
    return "hn:%d\t%d\t%d\t%s\t%s" % (i, score, comments, title, url)
with cf.ThreadPoolExecutor(max_workers=8) as ex:
    rows = [r for r in ex.map(item, ids) if r]
if not rows:
    sys.exit(1)
with open("hn-top.txt", "w", encoding="utf-8") as f:
    f.write("\n".join(rows) + "\n")
print("hn-top.txt %d items" % len(rows))
PY
